        let repo = JobRepository::new(pool);
        let jobs = repo.list_jobs(filters.clone(), limit, None, CursorDirection::Forward).await?;
        let total = repo.count_jobs(filters).await?;
        Ok::<_, crate::jobs::error::JobError>((jobs, total))
    });

    match result {
        Ok((jobs, total)) => {
